import os
import psycopg2
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def sanitize_order(order_val):
    """Allow only asc/desc for ORDER BY direction"""
    if order_val and order_val.lower() in ('asc', 'desc'):
        return order_val.lower()
    return 'asc'

def validate_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', '')
    if len(key) != len(expected):
        return False
    result = 0
    for a, b in zip(key.encode(), expected.encode()):
        result |= a ^ b
    return result == 0

@app.before_request
def check_auth():
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate filtered report based on user criteria"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    report_type = data.get('report_type', 'summary')
    date_from = data.get('date_from', '2024-01-01')
    date_to = data.get('date_to', '2024-12-31')
    group_by = data.get('group_by', 'department')
    filters = data.get('filters', {})
    order = sanitize_order(data.get('order'))

    # Build base query with parameterized dates
    base_query = """
        SELECT {columns}
        FROM employee_records e
        JOIN departments d ON e.dept_id = d.id
        WHERE e.created_at BETWEEN %s AND %s
    """

    columns = "e.id, e.name, e.email, d.name as dept, e.salary"
    if report_type == 'aggregate':
        columns = f"d.name as dept, COUNT(*) as cnt, AVG(e.salary) as avg_sal"

    query = base_query.format(columns=columns)
    params = [date_from, date_to]

    # Apply dynamic filters - group_by is validated against allowed set
    allowed_groups = ['department', 'role', 'location', 'hire_year']

    # Apply category filter
    if 'category' in filters:
        category = filters['category']
        query += f" AND e.category = '{category}'"

    if report_type == 'aggregate' and group_by in allowed_groups:
        group_col = {'department': 'd.name', 'role': 'e.role',
                     'location': 'e.location', 'hire_year': 'EXTRACT(YEAR FROM e.hire_date)'}[group_by]
        query += f" GROUP BY {group_col}"

    query += f" ORDER BY 1 {order}"

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        col_names = [desc[0] for desc in cur.description]
        results = [dict(zip(col_names, row)) for row in rows]
        cur.close()
        return jsonify({'data': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/reports/templates', methods=['GET'])
def list_templates():
    """List available report templates"""
    templates = [
        {'id': 1, 'name': 'Monthly Summary', 'type': 'summary'},
        {'id': 2, 'name': 'Department Breakdown', 'type': 'aggregate'},
        {'id': 3, 'name': 'Salary Analysis', 'type': 'aggregate'},
    ]
    return jsonify({'templates': templates})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
